SELECT * FROM (SELECT CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END AS rating_bucket, SORT_ARRAY(COLLECT_SET(country)) AS country_list, ROUND((100 * SUM(CASE WHEN country = 'UK' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_uk FROM suppliers GROUP BY CASE WHEN rating >= 3.6 THEN 'high' WHEN rating >= 2.2 THEN 'mid' ELSE 'low' END) AS x WHERE pct_uk < 57 ORDER BY pct_uk, rating_bucket;
